// Generate `src/version.ts` for every workspace package from its package.json version.
//
// Usage: node .github/scripts/generate-versions.mjs
//
// Runs from each package's `prebuild` and from the root `install` script. A package build
// compiles other packages' sources through tsconfig references, so one build needs every
// package's version file, not only its own. Files are written only when missing or stale,
// and atomically, so concurrent builds never observe a partially written file. The output
// matches `genversion --es6 --semi`, which previously generated these files.

import { existsSync, globSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../..');

/** Workspace package manifests, mirroring the globs in pnpm-workspace.yaml. */
const manifestPaths = globSync(
  ['packages/**/package.json', 'cookbooks/*/package.json', 'vue-press/package.json'],
  {
    cwd: repoRoot,
    exclude: (path) => path.includes('node_modules') || path.includes('/dist/'),
  },
);

let written = 0;

// Each package with a `src` directory gets a version module matching its manifest version.
for (const manifestPath of manifestPaths) {
  const packageDir = resolve(repoRoot, dirname(manifestPath));
  const { version } = JSON.parse(readFileSync(resolve(repoRoot, manifestPath), 'utf8'));
  // Packages without sources or a version have nothing to generate.
  if (!version || !existsSync(resolve(packageDir, 'src'))) continue;

  const target = resolve(packageDir, 'src/version.ts');
  const content = `// Generated by genversion.\nexport const version = '${version}';\n`;
  // Skip unchanged files so parallel builds do not rewrite files other compiles are reading.
  if (existsSync(target) && readFileSync(target, 'utf8') === content) continue;

  // Rename over the target so readers see either the old or the new file, never a partial one.
  const temporary = `${target}.${process.pid}.tmp`;
  writeFileSync(temporary, content);
  renameSync(temporary, target);
  written++;
}

if (written > 0) {
  console.log(`Generated ${written} version file(s).`);
}
